class ChatBot:
    def __init__(self):
        self.history = []

    def detect_intent(self, text):
        text_lower = text.lower()
        if any(w in text_lower for w in ['退款', '退货', '换货']):
            return 'refund'
        if any(w in text_lower for w in ['价格', '多少钱', '费用']):
            return 'pricing'
        return 'general'

    def chat(self, user_input):
        intent = self.detect_intent(user_input)
        self.history.append({'user': user_input, 'intent': intent})
        if intent == 'refund':
            return '关于退款问题，请在订单页面操作或联系客服。'
        elif intent == 'pricing':
            return '请查看我们的价格页面了解详情。'
        return '您好，有什么可以帮您的？'

