class Pipeline:
    def __init__(self):
        self.steps = []

    def add_step(self, name, func):
        self.steps.append((name, func))

    def run(self, data):
        for name, func in self.steps:
            data = func(data)
        return data

    def run_with_log(self, data):
        logs = []
        for name, func in self.steps:
            data = func(data)
            logs.append({'step': name, 'status': 'done', 'data_len': len(data) if hasattr(data, '__len__') else 0})
        return data, logs

