class AITutor:
    def __init__(self):
        self.user_profile = {}
        self.knowledge = {}

    def update_profile(self, user_id, topic, score):
        if user_id not in self.user_profile:
            self.user_profile[user_id] = {}
        self.user_profile[user_id][topic] = score

    def recommend(self, user_id):
        weak = self.get_weak_areas(user_id)
        if weak:
            return f'建议复习: {weak[0]}'
        return '所有领域表现优秀，继续探索新知识！'

    def get_weak_areas(self, user_id):
        profile = self.user_profile.get(user_id, {})
        weak = [topic for topic, score in profile.items() if score < 60]
        return sorted(weak, key=lambda t: profile[t])
